function Counter() {
  const [count, setCount] = useState(0);

  const handleClick = () => {
    setCount(count + 1); // Uses stale closure
    setCount(count + 1); // Uses same stale value
    console.log(count);  // Still 0 (state hasn't updated yet)
  };

